transformations.before:
assert.equal(sha(path.resolve(ROOT, policy.review.tool)), policy.review.toolSha256, 'Original frozen reviewer must remain unchanged');
const originalReviewFile = path.join(folder, 'review.json'), originalReview = read(originalReviewFile);
assert.equal(originalReview.status, 'incomplete-or-invalid-data');
assert.equal(originalReview.reviewTool.sha256, policy.review.toolSha256);
assert(originalReview.inputs.some(row => path.resolve(row.path) === summaryFile && row.sha256 === sha(summaryFile)));
for (const row of originalReview.inputs) assert.equal(sha(row.path), row.sha256, `Original failed-review input changed: ${row.path}`);

transformations.after:
assert.equal(path.resolve(ROOT, policy.review.tool), fileURLToPath(import.meta.url), 'Use the reviewer frozen before the continuous run');
assert.equal(sha(fileURLToPath(import.meta.url)), policy.review.toolSha256);
assert.equal(policy.algorithmRevision, 6); assert.equal(policy.review.predeclared, true);
assert.equal(policy.worldIds.length, 108); assert.equal(new Set(policy.worldIds).size, 108);
const derivation = read(policy.review.derivation.path);
assert.equal(sha(policy.review.derivation.path), policy.review.derivation.sha256);
assert.equal(derivation.original.path, 'tools/qa/r100-i09-review-continuous-death-loss.mjs');
assert.equal(derivation.original.sha256, 'ecdeb748031d5ba0fe31a8240831271ce9b63e79170b01db5498ebf595c00707');
assert.equal(sha(path.resolve(ROOT, derivation.original.path)), derivation.original.sha256);
assert.equal(derivation.executor.sha256, policy.review.toolSha256);

assert.equal(data.policyRevision, 15);
assert.equal(data.harnessSha256, policy.fixedFiles.find(row => row.file === policy.harness)?.sha256);
for (const dependency of data.harnessDependencies) assert.equal(dependency.sha256, policy.fixedFiles.find(row => row.file === dependency.file)?.sha256);
